const notices = $input.all().map(i => i.json);
return notices.map(n => ({
  json: {
    title: n.title,
    stage: n.stage,
    buyerName: n.buyerName,
    contactName: n.contactName,
    contactEmail: n.contactEmail,
    valueGBP: n.valueGBP,
    deadlineDate: n.deadlineDate,
    suitableForSME: n.suitableForSME,
    noticeUrl: n.noticeUrl,
    agentSummary: n.agentSummary
  }
}));
